{"@context":"http://schema.org/","@type":"Dataset","url":"https://navigator.eumetsat.int/product/EO:EUM:DAT:0862","measurementTechnique":"Radiometer","copyrightHolder":{"@type":"Organization","name":"EUMETSAT","contactPoint":{"@type":"ContactPoint","contactType":"customer support","email":"ops@eumetsat.int","url":"https://user.eumetsat.int"}},"copyrightYear":"1978","creator":{"@type":"Organization","name":"EUMETSAT","contactPoint":{"@type":"ContactPoint","contactType":"customer support","email":"ops@eumetsat.int","url":"https://user.eumetsat.int"}},"dateCreated":"Thu Jan 05 00:11:00 UTC 1978","isAccessibleForFree":"false","keywords":"GEO,Metop,Climate,TIROS,Climate system monitoring - Atmosphere,NOAA,netCDF4,NWP-based reanalysis,Radiometer,AVHRR","license":"https://eoportal.eumetsat.int/userMgmt/terms.faces","publisher":{"@type":"Organization","name":"EUMETSAT","contactPoint":{"@type":"ContactPoint","contactType":"customer support","email":"ops@eumetsat.int","url":"https://user.eumetsat.int"}},"schemaVersion":"3.5","spatialCoverage":{"@type":"Place","geo":{"@type":"GeoShape","polygon":"-180.0  90.0  180.0  -90.0"}},"temporalCoverage":"Thu Jan 05 00:11:00 UTC 1978 / Tue Jan 30 00:06:00 UTC 2024","thumbnailUrl":"https://user.eumetsat.int/s3/eup-strapi-media/pygac_fdr_r1_2_a2d95338d0.png","encodingFormat":"netCDF4","description":"This AVHRR Fundamental Data Record (FDR) consists of reflectance and brightness temperatures. The FDR was homogeneously produced for a period ranging from 1978 – 2021 using PyGAC (a Python software package to read, calibrate and navigate AVHRR data in GAC format). It is based on observations from 17 AVHRR instruments on board NOAA satellites TIROS-N to NOAA-19, as well as EUMETSAT satellites Metop-A, -B, and -C. For calibration the PATMOS-X calibration coefficients have been applied to visible channels and the nominal operational calibration has been used for the infrared channels.

